# Cardiology and Resuscitation (NREMT AEMT test plan: 11% to 15%).
# AEMT scope (2019 Scope of Practice Model): 12-lead acquisition and transmission (not
# interpretation), AED, mechanical CPR device, aspirin, sublingual nitroglycerin. Manual
# defibrillation, pacing, cardioversion and 12-lead interpretation are paramedic skills.
# Figures: NASEMSO National Model EMS Clinical Guidelines v3.0 (2022), Chest Pain/ACS/STEMI,
# Adult Cardiac Arrest, Bradycardia, Ventricular Assist Device and Post-ROSC guidelines.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Aspirin for ACS", "What aspirin dose fits suspected cardiac chest pain in an adult with no allergy?",
      ["162 to 325 mg, chewed", "81 mg, swallowed whole", "650 mg, chewed", "1,000 mg, swallowed"],
      "Guidelines give 162 to 325 mg of chewable, non-enteric-coated aspirin, chewed so it absorbs fast. A single swallowed 81 mg tablet acts too slowly and too weakly, and 650 mg adds bleeding risk without benefit."),
    S(1, 2, "Nitroglycerin", "A man with chest pain took tadalafil for erectile dysfunction last night. What about nitroglycerin?",
      ["Withhold it", "Give half a dose", "Give it if SBP is over 90", "Give it by spray only"],
      "Nitrates are avoided within 48 hours of a phosphodiesterase inhibitor such as tadalafil or sildenafil, because together they can drop the blood pressure dangerously. A smaller dose or another form does not remove that risk."),
    S(1, 3, "Inferior STEMI", "The hospital reads your transmitted 12-lead as an inferior STEMI. BP is 98/62. What fits best?",
      ["Hold nitroglycerin", "Give nitroglycerin now", "Give a second aspirin", "Place him sitting bolt upright"],
      "Inferior infarcts often involve the right ventricle, which depends on preload, and NASEMSO gives nitroglycerin only when SBP is over 100. A second aspirin adds nothing, and an upright position lowers preload further."),
    O(1, 2, "12-lead acquisition", "Place the steps for acquiring and sending a 12-lead ECG in order.",
      ["Explain it and position him supine", "Clean and dry the skin sites", "Attach the four limb electrodes", "Attach V1 through V6", "Have him hold still; acquire", "Transmit it to the hospital"],
      "Explain and position first, prepare the skin so the electrodes stick, place limb leads then precordial leads, record while the patient is still, and transmit early so the receiving center can activate its team."),
    S(1, 2, "Lead placement", "Where does the V1 electrode go?",
      ["4th intercostal space, right sternal border", "4th intercostal space, left sternal border", "5th intercostal space, midclavicular line", "2nd intercostal space, right sternal border"],
      "V1 sits in the fourth intercostal space just right of the sternal border and V2 mirrors it on the left. The fifth space at the midclavicular line is V4."),
    S(1, 3, "CPR quality", "During CPR, ETCO2 reads 8 mm Hg and has stayed there for several minutes. What does this most likely show?",
      ["Compressions need to improve", "The patient has a pulse again", "The airway device is in the esophagus", "Ventilations are too slow"],
      "During CPR, ETCO2 reflects the blood flow compressions create, and readings under about 10 mm Hg suggest poor compressions, so push harder and faster and change compressors. A waveform that is present shows the airway is in place."),
    M(1, 2, "Return of circulation", "Which findings suggest return of spontaneous circulation during a resuscitation? Select three.",
      ["ETCO2 jumps from 14 to 41 mm Hg", "A carotid pulse you can feel", "He starts to move and gag", "The AED advises no shock", "Pupils are fixed and wide", "SpO2 probe shows no signal"],
      "A sudden ETCO2 rise, a palpable pulse and purposeful movement all point to ROSC. A no-shock advisory may mean asystole or PEA, and fixed pupils or no oximetry signal do not show circulation."),
    S(1, 2, "CPR with an advanced airway", "An adult in cardiac arrest now has a supraglottic airway. How should breaths be given?",
      ["1 every 6 seconds, no pauses", "2 breaths after every 30 compressions", "1 every 3 seconds with pauses", "Only when the AED analyzes"],
      "Once an advanced airway is in, compressions continue without pauses and one breath is given every 6 seconds. The 30:2 pause is for BVM ventilation without an advanced airway."),
    S(1, 2, "Pulmonary edema", "An alert patient with acute pulmonary edema has BP 188/104. Which drug best lowers preload?",
      ["Nitroglycerin", "A 500 mL saline bolus", "Nebulized albuterol", "Oral glucose"],
      "Nitroglycerin dilates veins and pools blood away from the lungs, and it pairs with CPAP in hypertensive pulmonary edema. A fluid bolus adds to the congestion, and albuterol treats bronchospasm."),
    S(1, 3, "Aortic dissection", "Sudden tearing chest pain spreads to the back, and the BP is 30 mm Hg higher in the right arm. What fits?",
      ["Withhold aspirin; transport", "Give aspirin and nitroglycerin", "Give a 1 L fluid bolus", "Walk him to the ambulance"],
      "Tearing pain to the back with unequal arm pressures suggests aortic dissection, where aspirin can worsen bleeding. He needs gentle handling and rapid transport, not exertion or large fluid volumes."),
    # ---------- Practice Test 2 ----------
    X(2, 2, "Nitroglycerin decisions", "Each patient has ongoing chest pain of suspected cardiac origin. Specify whether nitroglycerin may be given.",
      ["SBP 146, no recent ED drugs", "Took sildenafil 20 hours ago", "SBP 94 after one tablet", "Pain persists 5 minutes after a dose, SBP 134"],
      ["Give nitroglycerin", "Withhold nitroglycerin"], [0, 1, 1, 0],
      "Nitroglycerin 0.4 mg SL may be repeated every 3 to 5 minutes while SBP stays over 100. A phosphodiesterase inhibitor within 48 hours, or a systolic pressure at or below 100, rules out the next dose."),
    O(2, 1, "AED use", "Place the steps for using an AED on an adult in cardiac arrest in order.",
      ["Turn on the AED", "Apply pads to the bare chest", "Stop CPR and clear for analysis", "Clear everyone; deliver the shock", "Resume compressions at once"],
      "Power on, place pads, let it analyze with no one touching, clear and shock, then go straight back to compressions for 2 minutes. Checking a pulse right after the shock delays the compressions the heart needs."),
    S(2, 2, "Post-resuscitation ventilation", "After ROSC, how should you ventilate a patient who is not breathing on his own?",
      ["To an ETCO2 of 35 to 45", "As fast as the bag refills", "To an ETCO2 under 25 mm Hg", "Only when SpO2 drops below 85"],
      "After ROSC, aim for normal ventilation: an ETCO2 of 35 to 45 mm Hg and an SpO2 in the 90s. Hyperventilation lowers CO2, narrows brain vessels and reduces return of blood to the heart."),
    S(2, 2, "Scope of practice", "A patient with HR 36 is pale and hypotensive. Which treatment is outside AEMT scope?",
      ["Transcutaneous pacing", "Oxygen by nasal cannula", "Peripheral IV access", "12-lead acquisition"],
      "Transcutaneous pacing, like manual defibrillation and cardioversion, is a paramedic skill in the national scope model. An AEMT can give oxygen, start an IV, acquire the 12-lead and request ALS."),
    S(2, 3, "Ventricular assist device", "A patient with an LVAD is alert and talking, but you cannot feel a pulse. How do you judge perfusion?",
      ["Mental status and skin", "Start chest compressions", "Radial pulse at both wrists", "Capillary refill alone"],
      "Continuous-flow LVADs often leave no palpable pulse, so an alert patient with warm, dry skin is perfusing. Listen for the pump hum, check for alarms and call the VAD coordinator whose number is on the device."),
    S(2, 2, "Atypical ACS", "Which patient is most likely to have a heart attack with no chest pain at all?",
      ["A 74-year-old with diabetes", "A 40-year-old marathon runner", "A 35-year-old with asthma", "A 52-year-old smoker"],
      "Older adults, people with diabetes and women often present with weakness, shortness of breath or nausea instead of chest pain. Smoking raises risk but does not make the pain atypical."),
    S(2, 2, "STEMI destination", "Why transmit a 12-lead showing a possible STEMI before arrival?",
      ["The center can ready its cath lab", "It replaces the hospital's own ECG", "It lets you give thrombolytics", "It is required to give aspirin"],
      "Advance notification lets a PCI center activate its team so the artery opens sooner. AEMTs do not give thrombolytics, and aspirin does not wait for an ECG."),
    S(2, 1, "Angina", "Chest pain began while shoveling snow and went away with rest within 5 minutes. This pattern suggests:",
      ["Stable angina", "Aortic dissection", "Pericarditis", "Pulmonary embolism"],
      "Pain brought on by exertion and relieved by rest is the classic pattern of stable angina. A dissection tears suddenly, pericarditis changes with position, and an embolism brings sudden shortness of breath."),
    S(2, 3, "Exertional syncope", "A 16-year-old athlete fainted while sprinting and recovered quickly. Why is this concerning?",
      ["It may be cardiac", "It is a sign of dehydration", "It suggests low blood sugar", "It shows a seizure disorder"],
      "Fainting during exertion, unlike fainting after standing up, can come from a structural heart problem or an arrhythmia and needs a cardiac workup. Dehydration usually causes fainting after effort or when standing."),
    S(2, 2, "Nitroglycerin effects", "After a nitroglycerin tablet, the patient says his head pounds. What explains this?",
      ["Dilated blood vessels", "An allergic reaction", "A stroke in progress", "Low blood sugar from fasting"],
      "Nitroglycerin dilates vessels, including those in the head, so a throbbing headache is a common, expected effect. Recheck the BP because the same dilation can cause hypotension."),
    # ---------- Drill only ----------
    M(0, 3, "Aortic dissection", "Which findings point toward aortic dissection rather than a heart attack? Select two.",
      ["Tearing pain that goes to the back", "Arm pressures differ by 25 mm Hg", "Pressure relieved by nitroglycerin", "Pain eased by leaning forward", "Pain you reproduce by pressing"],
      "Sudden tearing pain radiating to the back and unequal arm pressures suggest a dissection. Relief by leaning forward points to pericarditis, and pain reproduced by palpation suggests a chest wall cause."),
    S(0, 2, "Lead placement", "Where is the V4 electrode placed?",
      ["5th intercostal space, midclavicular line", "4th intercostal space, right of the sternum", "5th intercostal space, midaxillary line", "6th intercostal space, anterior axillary line"],
      "V4 sits in the fifth intercostal space at the midclavicular line, V5 at the anterior axillary line on that level and V6 at the midaxillary line."),
    S(0, 2, "Compression pauses", "Why keep the pause before an AED shock as short as possible?",
      ["Coronary flow drops each pause", "Long pauses drain the AED battery", "The pads cool while paused", "The AED cannot analyze after a pause"],
      "Blood flow to the heart builds slowly during compressions and drops quickly when they stop, so long pauses make a shock less likely to work. Battery and pad temperature are not the reason."),
    S(0, 2, "Mechanical CPR", "When is a mechanical CPR device most helpful?",
      ["While moving him to the ambulance", "In the first minute of a witnessed arrest", "When the AED advises a shock", "Before the airway is opened"],
      "A device keeps compressions steady on stairs and in a moving ambulance, where manual CPR is poor and unsafe. Applying it should not delay early compressions or a shock."),
    S(0, 3, "Cardiogenic shock", "After a large heart attack, BP is 80/50 with crackles in both lungs. What fits the fluid plan?",
      ["Small boluses, recheck lungs", "Two liters wide open", "No IV access at all", "Fluids only if HR exceeds 150"],
      "A failing heart cannot handle large volumes, so any fluid goes in small boluses with frequent lung checks, while ALS and the receiving center are alerted. Withholding IV access removes a route for ALS drugs."),
    S(0, 1, "STEMI destination", "Where should a patient with a transmitted STEMI usually be taken?",
      ["PCI-capable center", "The nearest urgent care", "Any hospital with a lab", "His cardiologist's office"],
      "A center that can open the artery in the cath lab shortens time to reperfusion. Urgent care centers and offices cannot treat a STEMI, so the patient would need a second transfer."),
]
